// Bundle the pre-rendered Bloub cards (assets/bloub/*.svg) into src/bloub-cards.js, so the
// Vercel function and the Cloudflare Worker can both serve them without filesystem access.
//   node scripts/build-bloub.mjs
//
// The SVGs themselves are generated by scripts/bloub-cards.ts (see the header there).
import { readFileSync, writeFileSync } from "node:fs";
import { compactSvg } from "./svg-compact.mjs";

// compactSvg: lossless rewrite (exact geometry, ~20-28% smaller), see svg-compact.mjs
const read = (name) => compactSvg(readFileSync(new URL(`../assets/bloub/${name}.svg`, import.meta.url), "utf8"));
const cards = {
  coding: { dark: read("coding-dark"), light: read("coding-light") },
  idle: { dark: read("sleeping-dark"), light: read("sleeping-light") },
};

writeFileSync(
  new URL("../src/bloub-cards.js", import.meta.url),
  "// GENERATED by scripts/build-bloub.mjs from assets/bloub/*.svg. Do not edit by hand.\n" +
    `export const BLOUB_CARDS = ${JSON.stringify(cards)};\n`
);
console.log("wrote src/bloub-cards.js");
